          font-weight: normal;
          text-decoration: underline double black !important;
          display: inline;
     }
     #listbuttons li {
          margin-right: 1.6em;
          margin-left: 2.5em;
          font-family: Verdana;
          font-size: 8px;
          display: inline;
          font-variant: small-caps;
          letter-spacing: 2px;
     }
     #quicklinks div {
          float: left;
          font-size: 9px;
          letter-spacing: 0.6px;
     }
}

